220	    /** A steward approves a PENDING claim: it becomes SETTLED, its due (its live figure, with its
221	     *  late charge) frozen now. Refused (409) unless PENDING, (403) for a clerk or the user who
222	     *  opened it, and (423) when it is dated in a closed period. */
223	    @Transactional
224	    public Claim approve(String sheetId, String user, long id) {
225	        Claim claim = pendingForSteward(sheetId, user, id);
226	        if (user.equals(claim.getOpenedBy())) {
227	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
228	                    "The user who opened a claim cannot approve it");
229	        }
230	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
231	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
232	        RollupService.Snapshot before = rollup.snapshot(sheetId);
233	        BigDecimal due = shownDueOf(claim, person);
234	        claim.setStatus(ClaimStatus.SETTLED);
235	        claim.setSettledDue(due);
236	        claims.flush();
237	        logStatus(user, person, claim);
238	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), " due=" + dueText(due));
239	        rollup.recordChanges(sheetId, user, before);
240	        return claim;
241	    }
242	
243	    /** A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by the
244	     *  person's last statement if that statement bound it. Refused (409) unless PENDING, (403) for
245	     *  a clerk, and (423) when it is dated in a closed period. */
246	    @Transactional
247	    public Claim reject(String sheetId, String user, long id, String reason) {
248	        Claim claim = pendingForSteward(sheetId, user, id);
249	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
250	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
251	        RollupService.Snapshot before = rollup.snapshot(sheetId);
252	        claim.setStatus(ClaimStatus.OPEN);
253	        claims.flush();
254	        logStatus(user, person, claim);
255	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), " reason=" + reason);
256	        rollup.recordChanges(sheetId, user, before);
257	        return claim;
258	    }
259	
260	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet: it keeps its
261	     *  number and date, is listed as the new person's newest claim, and loses any figure a
262	     *  statement bound it to (live again until the new person's next statement). Refused (404)
263	     *  when the claim or person is missing, (423) when it is dated in a closed period, (403) for a
264	     *  clerk, (409) when SETTLED or VOID or already the person's, and (422) when it is dated after
265	     *  the new person's retirement date. */
266	    @Transactional
267	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
268	        Claim claim = claims.findForUpdate(id, sheetId)
269	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
270	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
271	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
272	        refuseIfClosed(sheetId, claim.getDate());
273	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
274	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward reassigns a claim");
275	        }
276	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
277	            throw new ResponseStatusException(HttpStatus.CONFLICT,
278	                    "A " + claim.getStatus() + " claim cannot be reassigned");
279	        }
280	        if (claim.getPersonId() == toPersonId) {
281	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already that person's");
282	        }
283	        refuseIfRetired(to, claim.getDate());
284	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
285	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
286	        RollupService.Snapshot before = rollup.snapshot(sheetId);
287	        claim.setPersonId(to.getId());
288	        claim.unbind();
289	        claim.setListed(claims.findLastListed(sheetId) + 1);
290	        claims.flush();
291	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(),
292	                " from=" + from.getName() + " to=" + to.getName());
293	        rollup.recordChanges(sheetId, user, before);
294	        return claim;
295	    }
296	
297	    /** The PENDING claim a steward decides on: refused (404) when missing, (423) when dated in a
298	     *  closed period, (409) unless PENDING, and (403) when the user is not a steward. */
299	    private Claim pendingForSteward(String sheetId, String user, long id) {
300	        Claim claim = claims.findForUpdate(id, sheetId)
301	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
302	        refuseIfClosed(sheetId, claim.getDate());
303	        if (claim.getStatus() != ClaimStatus.PENDING) {
304	            throw new ResponseStatusException(HttpStatus.CONFLICT,
305	                    "Only a PENDING claim is approved or rejected, not a " + claim.getStatus() + " one");
306	        }
307	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
308	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
309	                    "Only a steward approves or rejects a PENDING claim");
310	        }
311	        return claim;
312	    }
313	
314	    /** Write the claim's status now to its log: by the user, on the sheet's today, with the due
315	     *  it shows at this moment. */
316	    private void logStatus(String user, Person person, Claim claim) {
317	        BigDecimal due = shownDueOf(claim, person);
318	        log.save(new ClaimLog(claim.getSheetId(), claim.getId(), claim.getStatus(), user,
319	                sheets.today(claim.getSheetId()), due == null ? null : due.setScale(2, RoundingMode.HALF_EVEN)));
320	    }
321	
322	    private static String dueText(BigDecimal due) {
323	        return due == null ? "n/a" : due.toPlainString();
324	    }
325	
326	    /** Take a statement of a person: record their due-total now, and bind each of their claims
327	     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold) to its figure now; the others
328	     *  are left unbound. */
329	    @Transactional
330	    public Statement statement(String sheetId, String user, long personId) {
331	        Person person = people.findForUpdate(personId, sheetId)
332	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
333	        LocalDate today = sheets.today(sheetId);
334	        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
335	        RollupService.Snapshot before = rollup.snapshot(sheetId);
336	        List<Claim> counted = theirs.stream().filter(c -> counts(c, person)).toList();
337	        BigDecimal dueTotal = Sheet.capped(dueTotalOf(counted, person, today), sheets.cap(sheetId));
338	        for (Claim c : theirs) {
339	            if (counts(c, person)) {
340	                // the statement binds the figure; the late charge keeps following the sheet's today
341	                c.bind(c.getSettledDue() != null ? c.getSettledDue() : figureOf(c, person));
342	            } else {
343	                c.unbind();
344	            }
345	        }
346	        claims.flush();
347	        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
348	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
349	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
350	        rollup.recordChanges(sheetId, user, before);
351	        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
352	    }
353	
354	    /** The number a claim dated {@code date} takes as it is opened: under period numbering (set,
355	     *  and the sheet's today on or after it) the next within the period containing the date
356	     *  (<period name>-<n>), or X-<n> when none does; otherwise the sheet's next number. */
357	    private String nextNumber(String sheetId, LocalDate date) {
358	        if (!sheets.periodNumberingOn(sheetId)) {
359	            return String.valueOf(sheets.nextClaimNumber(sheetId));
360	        }
361	        // held until the transaction ends, so two claims opened at once are numbered one after the other
362	        sheets.lock(sheetId);
363	        String prefix = periods.containing(sheetId, date).map(Period::getName).orElse(NO_PERIOD) + "-";
364	        int last = claims.findNumbers(sheetId).stream()
365	                .filter(n -> n.startsWith(prefix))
366	                .map(n -> n.substring(prefix.length()))
367	                .filter(n -> n.matches("\\d{1,9}"))
368	                .mapToInt(Integer::parseInt)
369	                .max().orElse(0);
370	        return prefix + (last + 1);
371	    }
372	
373	    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
374	     *  the transaction ends so a period cannot be closed meanwhile. */
375	    private void refuseIfClosed(String sheetId, LocalDate date) {
376	        sheets.lock(sheetId);
377	        periods.refuseIfClosed(sheetId, date);
378	    }
379	
380	    /** The number a claim of the amount corrects: none unless the amount is negative, when it must
381	     *  be the number of a SETTLED claim of the same person, or the claim is refused (422). */
382	    private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
383	        if (amount.signum() >= 0) {
384	            return null;
385	        }
386	        if (corrects == null
387	                || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
388	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
389	                    "A negative amount must correct a settled claim of the same person");
390	        }
391	        return corrects;
392	    }
393	
394	    /** Refuse (422) a claim dated after its person's retirement date. */
395	    private static void refuseIfRetired(Person person, LocalDate date) {
396	        if (person.retiredBefore(date)) {
397	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
398	                    "The date is after the person's retirement date");
399	        }
400	    }
401	
402	    /** Whether a claim counts toward claimed and due totals: only OPEN (or PENDING) and SETTLED ones
403	     *  do, but not an open one dated within a hold of its person unless bound by a statement. */
404	    private static boolean counts(Claim c, Person person) {
405	        return c.getStatus() == ClaimStatus.SETTLED
406	                || (c.getStatus().isOpen() && (c.isBound() || !person.heldOn(c.getDate())));
407	    }
408	
409	    /** The due a claim shows: the due fixed when it was settled, else its figure with its late
410	     *  charge on top. */
411	    private BigDecimal shownDueOf(Claim claim, Person person) {
412	        if (claim.getSettledDue() != null) {
413	            return claim.getSettledDue();
414	        }
415	        return LateCharge.of(sheets.find(claim.getSheetId())).addTo(claim, figureOf(claim, person), roundingOf(claim));
416	    }
417	
418	    /** A claim's figure before any late charge: the one a statement bound it to (null: n/a), else
419	     *  (unbound, or PENDING) its live due. */
420	    private BigDecimal figureOf(Claim claim, Person person) {
421	        return claim.isBound() ? claim.getStatedDue() : dueOf(claim, person);
422	    }
423	
424	    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
425	     *  null (n/a) when their grade in force on the sheet's today has no rate then, unless a claim
426	     *  shows a due (a fixed or bound one, or one at the rate of the grade they had on its date). */
427	    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
428	        List<BigDecimal> dues = counted.stream().map(c -> shownDueOf(c, person)).filter(d -> d != null).toList();
429	        if (rates.findInForce(person.getSheetId(), person.gradeOn(today), today).isEmpty() && dues.isEmpty()) {
430	            return null;
431	        }
432	        return dues.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
433	    }
434	
435	    /** The claim's amount times the rate, in force on the claim's date, of its person's grade then, divided by
436	     *  100, rounded as its rounding policy has it, raised to the sheet's floor (a correction's never is); null with no rate in force then. */
437	    private BigDecimal dueOf(Claim claim, Person person) {
438	        BigDecimal floor = sheets.floor(claim.getSheetId());
439	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
440	                .map(Rate::getPct)
441	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, roundingOf(claim)))
442	                .map(due -> claim.isCorrection() ? due : due.max(floor))
443	                .orElse(null);
444	    }
445	
446	    /** How the claim's live figures round: by the sheet's policy date against its date, or for a
447	     *  correction the date of the claim it corrects. */
448	    private RoundingMode roundingOf(Claim claim) {
449	        LocalDate on = claim.getCorrects() == null ? claim.getDate()
450	                : claims.findFirstBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
451	                        .map(Claim::getDate).orElse(claim.getDate());
452	        return Rounding.of(sheets.find(claim.getSheetId())).on(on);
453	    }
454	
455	    private void record(String event, String user, Person person, Claim claim) {
456	        record(event, user, person, claim, claim.getNumber());
457	    }
458	
459	    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
460	    private void record(String event, String user, Person person, Claim claim, String number) {
461	        record(event, user, person, claim, number, "");
462	    }
463	
464	    private void record(String event, String user, Person person, Claim claim, String number, String extra) {
465	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
466	                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
467	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
468	    }
469	
470	    private static String noteOf(String note) {
471	        return note == null ? "" : note.trim();
472	    }
473	}
